def minPath(grid, k):
    def dfs(x, y, path, visited):
        if len(path) == k:
            return True
        if x < 0 or x >= len(grid) or y < 0 or y >= len(grid[0]) or (x, y) in visited:
            return False
        visited.add((x, y))
        for dx, dy in [(0, 1), (1, 0), (-1, 0), (0, -1)]:
            if dfs(x + dx, y + dy, path + [grid[x][y]], visited):
                return True
        visited.remove((x, y))
        return False

    min_path = []
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if dfs(i, j, [], set()):
                min_path = sorted([grid[i][j]] + min_path)
                break
    return min_path
