def is_Monotonic(arr):
    # Check if the array is empty or has one element, which is considered monotonic
    if len(arr) <= 1:
        return True

    # Initialize two variables to track the direction of the change
    increasing = decreasing = False

    # Iterate through the array starting from the second element
    for i in range(1, len(arr)):
        # If the current element is greater than the previous one, decrease the increasing flag
        if arr[i] > arr[i - 1]:
            decreasing = True
        # If the current element is less than the previous one, increase the decreasing flag
        elif arr[i] < arr[i - 1]:
            increasing = True

    # If both flags are False, the array is monotonic
    return not (increasing or decreasing)
