def find_solution(a, b, n):
    # Check if there is a solution using the extended Euclidean algorithm
    def gcd(x, y):
        while y != 0:
            (x, y) = (y, x % y)
        return x

    # Calculate the greatest common divisor of a and b
    g = gcd(a, b)

    # If the GCD is not 1, there is no solution
    if g != 1:
        return None

    # Calculate the coefficients x and y
    x = n // b
    y = n - a * x

